      "passage": "Đọc đoạn tư liệu sau đây:\nVào thế kỉ VIII, người Ả Rập nhờ dịch tác phẩm Sít – han – ta mà học tập được chữ số Ấn Độ. Từ Ả Rập, hệ thống chữ số này được truyền sang châu Âu, do đó những chữ số này thường bị gọi nhầm là chữ số Ả Rập. Tư liệu sớm nhất về những chữ số này là các bia đá của A – sô – ca khắc từ thế kỉ III TCN. Tuy nhiên, con số 0 được thấy sớm nhất trong một tài liệu Ả rập năm 873, sau đó 3 năm mới thấy trong tài liệu Ấn Độ. Mặc dầu vậy, người ta vẫn cho rằng, số 0 cũng do người Ấn Độ sáng tạo.\n(Theo Vũ Dương Ninh (Chủ biên), Lịch sử văn minh thế giới, NXB Giáo dục, Hà Nội, 1991, tr.81)",
