      "passage": "Đọc đoạn tư liệu sau đây:\nSử thi Ra – ma – y – a – na có ảnh hưởng lớn ở các quốc gia Đông Nam Á. Hầu như mỗi nước đều có một phiên bản Ra – ma – y – a – na được bản địa hóa: truyện Ra – ma – kiên của Thái Lan; truyện Ra – ma – y – a – na của In – đô – nê – xi – a; kịch Ra – ma của Mi – an – ma; trường ca Riêm Kê của Cam – pu – chia; trường ca Phạ - lắc Phạ - lam và Xỉn – xay của Lào; truyện Ra – ma – y – a – na, Dạ Thoa Vương của Việt Nam.\n(Sách giáo khoa Lịch sử 10, bộ chân trời sáng tạo, tr. 34)",
