      "passage": "Đọc đoạn tư liệu sau đây:\nTừ thập niên 1780 trở đi, động cơ hơi nước đã được sử dụng ở các nhà máy. Những xưởng nấu sắt sử dụng máy hơi nước để chạy máy bơm hơi, giúp cho các lò cao có đầy đủ sức gió; các mỏ than đá dùng máy hơi nước để chạy máy bơm hút nước từ các hầm lò lên, ngành dệt dùng máy hơi nước để tạo ra động lực chuyển các công cụ. Năm 1785, người ta đã biết dùng máy hơi nước trong các xưởng dệt len nỉ. Năm 1789, người ta dùng máy hơi nước trong xưởng dệt vải. Chúng đã đạt được công suất từ 6 đến 20 mã lực, lớn hơn bất kì cối xay gió hay những guồng nước lớn nhất, đáng tin cậy hơn và được lắp đặt ở bất kì đâu. Đến năm 1800, toàn nước Anh đã có 321 cỗ máy hơi nước, với tổng công suất 5210 mã lực. Đến năm 1825 tăng lên 15000 cỗ máy hơi nước với tổng công suất 375000 mã lực.\n(Lưu Tộ Xương, Quang Nhân Hồng, Hàn Thừa Văn, Lịch sử thế giới cận đại (1640 – 1900), NXB Thành phố Hồ Chí Minh, TP. Hồ Chí Minh, 2002, tr.108)",
