      "passage": "Đọc đoạn tư liệu sau đây\n“Qua kết quả nghiên cứu xã hội và nhà nước Văn Lang đời Hùng Vương có thể ghi nhận đây là một hình thái xã hội đã có sự phân hóa sâu sắc nhưng chưa hình thành giai cấp đối kháng gay gắt, mà là những giai tầng xã hội với sự cách biệt đáng kể về của cải và xã hội, đó là tầng lớp quý tộc, tầng lớp nô tì tức nô lệ gia trưởng và tầng lớp dân tự do tức thành viên công xã nông thôn kiểu Á châu… Trên cơ sở phân hóa xã hội đó, kết hợp với yêu cầu phát triển nông nghiệp lúa nước gắn liền với yêu cầu thủy lợi và cả yêu cầu tự vệ, một nhà nước sơ khai đã ra đời. Đó là một hình thái nhà nước cổ đại ra đời đầu tiên trong lịch sử Việt Nam và cũng vào loại sớm nhất ở vùng Đông Nam Á”.\n(Phan Huy Lê, Lịch sử và văn hóa Việt Nam tiếp cận bộ phận, NXB giáo dục, 2007, tr.90)",
