      "passage": "Đọc đoạn tư liệu sau đây\n“Cư dân Văn Lang – Âu Lạc có nền văn học truyền miệng phát triển, với nhiều truyện thần thoại, truyền thuyết, cổ tích kể về các vị thần, các nhân vật anh hùng, sự tích. Các truyện Lạc Long Quân và Âu Cơ, Sơn Tinh – Thủy Tinh, Tháng Gióng, Bánh chưng, bánh giầy, Trầu cau,…là những viên ngọc quý trong kho tàng văn học thời dựng nước.”\n(Sách giáo khoa lịch sử 10, Bộ chân trời sáng tạo, tr.68)",
