      "passage": "Đọc đoạn tư liệu sau đây:\nChữ viết ra đời sớm đã thúc đẩy văn học dân gian Chăm phát triển song hành với văn học viết tạo nên nền văn học Chăm phong phú, đa dạng. Văn học dân gian có gần 50 bài ca dao; khoảng 1500 câu tục ngữ, câu đố; hơn 100 truyện cổ, truyền thuyết đã được sưu tầm; hơn 100 bài ca lịch sử hay tụng ca. Văn học viết đã tìm hiểu được các thể loại: Văn bia kí có 250 minh văn sáng tác từ thế kỉ II đến thế kỉ XV bằng cả tiếng Phạn lẫn tiếng Chăm cổ; 5 sử thi, 4 trường ca trữ tình, thơ thế sự Glơng Anak, Twơn Phauw…, thơ triết lý Nau Ikak, Jadar; gia huấn ca…\nSử thi Chăm mang màu sắc thần thoại Ấn Độ thấm đượm triết lý Bà la môn và Hồi giáo. Đặc biệt Ariya Bini – Cam được xem là một trong những truyện tình hay nhất của văn chương nhân loại.",
