      "passage": "Đọc đoạn tư liệu sau đây:\nChăm – pa là nơi sản sinh những nhạc sĩ, nhạc công, vũ sư, vũ công kiệt xuất với những vũ khúc điêu luyện, lôi cuốn, còn để lại dấu tích trên các phù điêu và tượng tròn của các đền tháp. Âm nhạc và ca múa (múa tôn giáo, múa tập thể, múa độc diễn, múa đạo cụ, múa bóng) không thể thiếu trong sinh hoạt cộng đồng và các dịp lễ hội truyền thống như Rija Nưgar (mừng năm mới), Katê ở làng hay trên tháp. Đó là các dịp mà người Chăm thể hiện sự tưởng nhớ của mình đối với những người có công xây dựng đất nước, hay sự sùng bái một vài vị vua được thần hóa.\nCác điệu múa nghi lễ và dân gian phong phú, độc đáo của người Chăm hiện nay vẫn còn lưu truyền là múa âm dương (tiêu biểu cho tín ngưỡng phồn thực), múa roi, múa đạp lửa, múa quạt, múa đội nước, múa khăn, múa kiếm, múa chèo thuyền.",
